class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def KDistanceNodes(root: TreeNode, target: int, k: int) -> list[int]:
    if not root:
        return []

    # Build parent map and find target node
    parent = {}
    stack = [(root, None)]
    target_node = None
    while stack:
        node, par = stack.pop()
        if node.val == target:
            target_node = node
        parent[node] = par
        if node.left:
            stack.append((node.left, node))
        if node.right:
            stack.append((node.right, node))

    if not target_node:
        return []

    # BFS to find nodes at distance k
    visited = set()
    queue = [(target_node, 0)]
    result = []

    while queue:
        node, dist = queue.pop(0)
        if dist == k:
            result.append(node.val)
            continue
        if dist > k:
            continue
        visited.add(node)
        if node.left and node.left not in visited:
            queue.append((node.left, dist + 1))
        if node.right and node.right not in visited:
            queue.append((node.right, dist + 1))
        if node in parent and parent[node] not in visited:
            queue.append((parent[node], dist + 1))

    return sorted(result)
